import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { router } from 'kea-router'

import { commandLogic } from 'lib/components/Command/commandLogic'
import { FEATURE_FLAGS } from 'lib/constants'
import { featureFlagLogic } from 'lib/logic/featureFlagLogic'
import { removeProjectIdIfPresent } from 'lib/utils/kea-router'

import type { FeatureFlagsSet } from '../../lib/logic/featureFlagLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface terminalDockLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    dockOpen: boolean
    hasOpened: boolean
    requestedFolder: string | null
    terminalEnabled: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface terminalDockLogicActions {
    focusTerminal: () => {
        value: true
    }
    openInTerminal: (folder: string) => {
        folder: string
    }
    setDockOpen: (open: boolean) => {
        open: boolean
    }
    setRequestedFolder: (folder: string | null) => {
        folder: string | null
    }
    toggleTerminal: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface terminalDockLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        terminalEnabled: (featureFlags: FeatureFlagsSet) => boolean
    }
}

export type terminalDockLogicType = MakeLogicType<
    terminalDockLogicValues,
    terminalDockLogicActions,
    Record<string, any>,
    terminalDockLogicMeta
>

export const terminalDockLogic = kea<terminalDockLogicType>([
    path(['scenes', 'terminal', 'terminalDockLogic']),
    connect({ values: [featureFlagLogic, ['featureFlags']] }),
    actions({
        openInTerminal: (folder: string) => ({ folder }),
        setRequestedFolder: (folder: string | null) => ({ folder }),
        toggleTerminal: true,
        focusTerminal: true,
        setDockOpen: (open: boolean) => ({ open }),
    }),
    reducers({
        requestedFolder: [null as string | null, { setRequestedFolder: (_, { folder }) => folder }],
        dockOpen: [false, { setDockOpen: (_, { open }) => open }],
        hasOpened: [false, { setDockOpen: (state, { open }) => state || open }],
    }),
    selectors({
        terminalEnabled: [
            (s) => [s.featureFlags],
            (featureFlags: FeatureFlagsSet): boolean => !!featureFlags[FEATURE_FLAGS.POSTHOG_TERMINAL],
        ],
    }),
    listeners(({ actions, values, cache }) => ({
        openInTerminal: ({ folder }) => {
            if (!values.terminalEnabled) {
                return
            }
            actions.setRequestedFolder(folder)
            actions.setDockOpen(true)
            actions.focusTerminal()
        },
        toggleTerminal: () => {
            if (!values.terminalEnabled) {
                return
            }
            if (removeProjectIdIfPresent(router.values.location.pathname) === '/terminal') {
                actions.focusTerminal()
            } else {
                actions.setDockOpen(!values.dockOpen)
            }
        },
        setDockOpen: ({ open }) => {
            if (open) {
                cache.previousFocus = document.activeElement?.closest('[role="dialog"]')
                    ? cache.commandFocus
                    : document.activeElement
            } else {
                if (cache.previousFocus?.isConnected) {
                    cache.previousFocus.focus()
                }
            }
        },
        [commandLogic.actionTypes.openCommand]: () => {
            cache.commandFocus = document.activeElement
        },
        [commandLogic.actionTypes.toggleCommand]: () => {
            if (commandLogic.values.isCommandOpen) {
                cache.commandFocus = document.activeElement
            }
        },
        [featureFlagLogic.actionTypes.setFeatureFlags]: () => {
            if (!values.terminalEnabled && values.dockOpen) {
                actions.setDockOpen(false)
            }
        },
    })),
])
